export const deck=majors.map((m,i)=>({id:`major-${i}`,name:m[0],english:m[1],upright:m[2],reversed:m[3],advice:m[4],domain:'重要转折',suit:'major',rank:i}));
for(const [suit,name,domain] of suits) meanings[suit].forEach((m,i)=>deck.push({id:`${suit}-${i+1}`,name:name+ranks[i],english:engRanks[i]+' of '+suit[0].toUpperCase()+suit.slice(1),upright:m[0],reversed:m[1],advice:m[2],domain,suit,rank:i+1}));
export function randomInt(n){if(!Number.isInteger(n)||n<1)throw Error('Invalid range');const v=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(v)}while(v[0]>=limit);return v[0]%n}
export function shuffleDeck(){const a=deck.map(c=>({...c,reverse:randomInt(2)===1}));for(let i=a.length-1;i>0;i--){const j=randomInt(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
